class AudioSettings { final String quality; final double balance; final bool mono,equalizerEnabled; final Map<String,double> equalizerBands; const AudioSettings({this.quality='auto',this.balance=0,this.mono=false,this.equalizerEnabled=false,this.equalizerBands=const {}}); AudioSettings copyWith({String? quality,double? balance,bool? mono,bool? equalizerEnabled,Map<String,double>? equalizerBands})=>AudioSettings(quality:quality??this.quality,balance:balance??this.balance,mono:mono??this.mono,equalizerEnabled:equalizerEnabled??this.equalizerEnabled,equalizerBands:equalizerBands??this.equalizerBands); factory AudioSettings.fromJson(Map<String,dynamic> j)=>AudioSettings(quality:j['quality']??'auto',balance:(j['balance']??0).toDouble(),mono:j['mono']==true,equalizerEnabled:j['equalizer_enabled']==true,equalizerBands:Map<String,dynamic>.from(j['equalizer_bands']??{}).map((k,v)=>MapEntry(k,(v as num).toDouble()))); Map<String,dynamic> toJson()=>{'quality':quality,'balance':balance,'mono':mono,'equalizer_enabled':equalizerEnabled,'equalizer_bands':equalizerBands}; }